import sys


def base36_increment(s: str) -> str:
    """Increment a base-36 string by 1, returning the same length."""
    chars = list(s)
    for i in range(len(chars) - 1, -1, -1):
        c = chars[i]
        if "0" <= c <= "9":
            if c == "9":
                chars[i] = "A"
                return "".join(chars)
            else:
                chars[i] = chr(ord(c) + 1)
                return "".join(chars)
        elif "A" <= c <= "Z":
            if c == "Z":
                chars[i] = "0"
                # continue to carry
            else:
                chars[i] = chr(ord(c) + 1)
                return "".join(chars)
        else:
            raise ValueError(f"Unexpected character {c!r}")
    # If we carried all the way through, we've wrapped around.
    # Prefix with '1' would change length, but wrap to all zeros instead.
    return "".join(chars)


def main() -> None:
    try:
        with open("ids.txt") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("ORD-0000")
        return

    # Find the last non-empty line
    last_id = None
    for line in reversed(lines):
        line = line.strip()
        if line:
            last_id = line
            break

    if last_id is None:
        print("ORD-0000")
        return

    # Expect format ORD-XXXX
    if not last_id.startswith("ORD-") or len(last_id) != 8:
        print(f"Unexpected id format: {last_id!r}", file=sys.stderr)
        sys.exit(1)

    suffix = last_id[4:]
    next_suffix = base36_increment(suffix)
    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()

