#!/usr/bin/env python3

import sys

CHARS = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'  # base-36


def to_base36(n: int, width: int = 4) -> str:
    """Convert an integer to a zero-padded base-36 string of the given width."""
    result = ''
    for _ in range(width):
        result = CHARS[n % 36] + result
        n //= 36
    return result


def from_base36(s: str) -> int:
    """Convert a base-36 string to an integer."""
    val = 0
    for c in s:
        val = val * 36 + CHARS.index(c)
    return val


def next_id(last_id: str) -> str:
    suffix = last_id[4:]  # 4-character suffix after 'ORD-'
    n = from_base36(suffix) + 1
    return 'ORD-' + to_base36(n, width=4)


def main():
    with open('ids.txt') as f:
        lines = f.readlines()
    if not lines:
        print('ORD-0000')
        return
    last = lines[-1].strip()
    print(next_id(last))


if __name__ == '__main__':
    main()

